{
  "story": "Clients and servers establish reliable connections through a three-step sequence exchanging synchronization and acknowledgment flags.",
  "aha": {
    "stateId": "step3",
    "observation": "The final ACK confirms connection establishment, allowing bi-directional data transfer to begin safely."
  },
  "layout": {
    "preset": "stepper-card",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "picture",
      "kind": "fixed-picture",
      "bind": {
        "active": "inputs.stepIndex",
        "regions": "variant.regions",
        "values": "variant.states.active"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "variant.states.why",
        "target": "variant.states.calloutRegion",
        "text": "variant.states.sentence"
      }
    },
    {
      "id": "readout",
      "kind": "value-readout",
      "bind": {
        "values": "variant.states.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Handshake Step",
      "options": [
        "SYN",
        "SYN-ACK",
        "ACK"
      ]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset",
      "options": []
    }
  ],
  "data": {
    "variants": [
      {
        "label": "TCP Handshake",
        "regions": [
          {
            "id": "client",
            "label": "Client",
            "kind": "actor",
            "values": ["CLOSED", "SYN-SENT", "ESTABLISHED"]
          },
          {
            "id": "server",
            "label": "Server",
            "kind": "actor",
            "values": ["LISTEN", "SYN-RCVD", "ESTABLISHED"]
          }
        ],
        "states": [
          {
            "id": "step1",
            "label": "1. SYN",
            "short": "SYN",
            "sentence": "Client sends SYN to initiate connection.",
            "why": "Establishes initial sequence number.",
            "active": ["client"],
            "calloutRegion": "client",
            "readouts": [
              {
                "id": "r1",
                "label": "Client State",
                "value": "SYN-SENT"
              },
              {
                "id": "r2",
                "label": "Server State",
                "value": "LISTEN"
              }
            ]
          },
          {
            "id": "step2",
            "label": "2. SYN-ACK",
            "short": "SYN-ACK",
            "sentence": "Server responds with SYN-ACK.",
            "why": "Acknowledges client and syncs server.",
            "active": ["server"],
            "calloutRegion": "server",
            "readouts": [
              {
                "id": "r1",
                "label": "Client State",
                "value": "SYN-SENT"
              },
              {
                "id": "r2",
                "label": "Server State",
                "value": "SYN-RCVD"
              }
            ]
          },
          {
            "id": "step3",
            "label": "3. ACK",
            "short": "ACK",
            "sentence": "Client sends final ACK.",
            "why": "Connection is fully established.",
            "active": ["client", "server"],
            "calloutRegion": "client",
            "readouts": [
              {
                "id": "r1",
                "label": "Client State",
                "value": "ESTABLISHED"
              },
              {
                "id": "r2",
                "label": "Server State",
                "value": "ESTABLISHED"
              }
            ]
          }
        ]
      }
    ]
  }
}
